begin;
create table public.voice_model_budgets(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),session_id uuid not null unique references public.voice_sessions(id),model text not null,call_key text not null unique,maximum_tokens bigint not null check(maximum_tokens=100000),price_snapshot jsonb not null,created_at timestamptz not null default clock_timestamp());
alter table public.voice_model_budgets enable row level security;alter table public.voice_model_budgets force row level security;create policy mission_scope on public.voice_model_budgets using(private.owns_mission(mission_id))with check(private.owns_mission(mission_id));create trigger immutable_row before update or delete on public.voice_model_budgets for each row execute function private.immutable_row();grant select on public.voice_model_budgets to policy_role,voice_role;
create function public.bind_voice_model_budget(p_mission uuid,p_session uuid,p_model text,p_key text,p_price jsonb)returns void language plpgsql security definer set search_path=''as $$declare v public.voice_sessions;prior public.voice_model_budgets;begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);select*into strict v from public.voice_sessions where mission_id=p_mission and id=p_session;
 if not exists(select from public.model_usage_reservations r where r.mission_id=p_mission and r.run_id=v.task_id and r.call_key=p_key and r.ceiling_micro_usd>0)or length(coalesce(p_model,''))=0 or not(p_price?&array['source','observedAt','audioInputPerMillion','cachedAudioInputPerMillion','audioOutputPerMillion'])then raise exception 'validation: scoped sourced realtime dollar reservation required';end if;perform private.assert_safe_content(p_price);
 insert into public.voice_model_budgets(mission_id,session_id,model,call_key,maximum_tokens,price_snapshot)values(p_mission,p_session,p_model,p_key,100000,p_price)on conflict(session_id)do nothing;select*into strict prior from public.voice_model_budgets where session_id=p_session;if prior.model<>p_model or prior.call_key<>p_key or prior.price_snapshot<>p_price then raise exception 'invariant_violation: pinned voice model or price changed';end if;
end$$;
revoke all on function public.bind_voice_model_budget(uuid,uuid,text,text,jsonb)from public;grant execute on function public.bind_voice_model_budget(uuid,uuid,text,text,jsonb)to policy_role;
create table private.provider_dispatches(id uuid primary key default gen_random_uuid(),mission_id uuid not null references public.missions(id),dispatch_key text not null,kind text not null,provider text not null,credential_ref uuid not null references private.provider_credentials(ref),artifact_version_id uuid,request_hash text not null,task_key text not null,model_name text,status text not null check(status in('started','completed','ambiguous')),encrypted_result jsonb,created_at timestamptz not null default clock_timestamp(),unique(mission_id,dispatch_key),foreign key(mission_id,artifact_version_id)references public.artifact_versions(mission_id,id));
create function private.check_provider_dispatch(p_mission uuid,p_provider text,p_ref uuid,p_version uuid,p_kind text,p_task text,p_model text)returns void language plpgsql set search_path=''as $$begin
 perform private.lock_mission(p_mission);perform private.active_mission(p_mission);
 perform 1 from private.provider_credentials c join public.missions m on m.id=c.mission_id join public.founder_accounts a on a.id=c.account_id and a.founder_id=m.founder_id where c.mission_id=p_mission and c.ref=p_ref and c.provider=p_provider and c.sandbox_mode=m.sandbox_mode and a.status='connected'for share of a;
 if not found or exists(select from public.account_revocations r join private.provider_credentials c on c.account_id=r.account_id where c.ref=p_ref)then raise exception 'invariant_violation: provider account revoked or out of scope';end if;
 perform private.check_version(p_mission,p_version);
 if p_kind='voice_realtime'and not exists(select from public.voice_sessions v where v.mission_id=p_mission and v.task_id::text=p_task and v.openai_ref=p_ref and exists(select from public.voice_model_budgets b where b.session_id=v.id and b.model=p_model and b.maximum_tokens=100000)and public.voice_output_allowed(p_mission,v.id))then raise exception 'invariant_violation: voice session authority unavailable';end if;
end$$;
create function public.start_provider_dispatch(p_mission uuid,p_key text,p_kind text,p_provider text,p_ref uuid,p_version uuid,p_hash text,p_task text,p_model text)returns jsonb language plpgsql security definer set search_path=''as $$declare d private.provider_dispatches;begin
 perform private.require_role(array['policy_role','voice_role']);if private.caller_role()='voice_role'and p_kind<>'voice_realtime'then raise exception 'invariant_violation: voice preparation capability denied';end if;perform private.check_provider_dispatch(p_mission,p_provider,p_ref,p_version,p_kind,p_task,p_model);
 if p_kind not in('paypal_order','openai_image','openai_structured','browserbase_research','voice_realtime')or p_hash!~'^[a-f0-9]{64}$'or p_key!~'^[a-f0-9]{64}$'or(p_kind='paypal_order'and(p_provider<>'paypal'or p_version is null))or(p_kind in('openai_image','openai_structured','voice_realtime')and p_provider<>'openai')or(p_kind='browserbase_research'and p_provider<>'browserbase')then raise exception 'validation: invalid service dispatch capability';end if;
 select*into d from private.provider_dispatches where mission_id=p_mission and dispatch_key=p_key;
 if d.id is not null then if row(d.kind,d.provider,d.credential_ref,d.artifact_version_id,d.request_hash,d.task_key,d.model_name)is distinct from row(p_kind,p_provider,p_ref,p_version,p_hash,p_task,p_model)then raise exception 'invariant_violation: service dispatch key changed';end if;return jsonb_build_object('fresh',false,'status',d.status,'encrypted',d.encrypted_result);end if;
 insert into private.provider_dispatches(mission_id,dispatch_key,kind,provider,credential_ref,artifact_version_id,request_hash,task_key,model_name,status)values(p_mission,p_key,p_kind,p_provider,p_ref,p_version,p_hash,p_task,p_model,'started');return jsonb_build_object('fresh',true,'status','started');
end$$;
create function public.lock_provider_dispatch(p_mission uuid,p_key text)returns void language plpgsql security definer set search_path=''as $$declare d private.provider_dispatches;begin
 perform private.require_role(array['policy_role','voice_role']);perform private.assert_mission(p_mission);select*into strict d from private.provider_dispatches where mission_id=p_mission and dispatch_key=p_key;perform private.check_provider_dispatch(p_mission,d.provider,d.credential_ref,d.artifact_version_id,d.kind,d.task_key,d.model_name);if private.caller_role()='voice_role'and d.kind<>'voice_realtime'then raise exception 'invariant_violation: voice preparation capability denied';end if;if d.status<>'started'then raise exception 'invariant_violation: provider dispatch already resolved';end if;
end$$;
create function public.complete_provider_dispatch(p_mission uuid,p_key text,p_encrypted jsonb)returns void language plpgsql security definer set search_path=''as $$declare d private.provider_dispatches;begin
 perform private.require_role(array['policy_role','voice_role']);perform private.lock_mission(p_mission);select*into strict d from private.provider_dispatches where mission_id=p_mission and dispatch_key=p_key;if private.caller_role()='voice_role'then if d.kind<>'voice_realtime'then raise exception 'invariant_violation: voice preparation capability denied';end if;perform private.check_provider_dispatch(p_mission,d.provider,d.credential_ref,d.artifact_version_id,d.kind,d.task_key,d.model_name);end if;if p_encrypted is not null and not(p_encrypted?&array['iv','ciphertext','tag'])then raise exception 'validation: encrypted service result required';end if;
 if d.kind='voice_realtime'then insert into public.model_usage(mission_id,run_id,call_key,model,input_tokens,output_tokens,cached_input_tokens,cost_micro_usd,usage_complete,price_snapshot)select p_mission,v.task_id,b.call_key,b.model,0,0,0,null,false,b.price_snapshot from public.voice_model_budgets b join public.voice_sessions v on v.id=b.session_id where b.mission_id=p_mission and v.task_id::text=d.task_key and b.model=d.model_name on conflict(call_key)do nothing;end if;
 update private.provider_dispatches set status=case when p_encrypted is null then'ambiguous'else'completed'end,encrypted_result=p_encrypted where mission_id=p_mission and dispatch_key=p_key and status='started';if not found then raise exception 'invariant_violation: provider dispatch already resolved';end if;
end$$;
create function public.lock_model_dispatch(p_mission uuid,p_run uuid,p_key text)returns void language plpgsql security definer set search_path=''as $$begin
 perform private.require_role(array['policy_role']);perform private.lock_mission(p_mission);perform private.active_mission(p_mission);
 if not exists(select from public.model_usage_reservations r where r.mission_id=p_mission and r.run_id=p_run and r.call_key=p_key and not exists(select from public.model_usage u where u.call_key=r.call_key))then raise exception 'invariant_violation: current scoped model reservation required';end if;
end$$;
revoke all on function public.lock_model_dispatch(uuid,uuid,text)from public;
grant execute on function public.lock_model_dispatch(uuid,uuid,text)to policy_role;
revoke all on function private.check_provider_dispatch(uuid,text,uuid,uuid,text,text,text)from public;
revoke all on function public.start_provider_dispatch(uuid,text,text,text,uuid,uuid,text,text,text),public.lock_provider_dispatch(uuid,text),public.complete_provider_dispatch(uuid,text,jsonb)from public;
grant execute on function public.start_provider_dispatch(uuid,text,text,text,uuid,uuid,text,text,text),public.lock_provider_dispatch(uuid,text),public.complete_provider_dispatch(uuid,text,jsonb)to policy_role,voice_role;
create or replace function public.resolve_provider_credential(p_mission uuid,p_ref uuid,p_provider text,p_sandbox boolean)returns jsonb language plpgsql security definer set search_path=''as $$declare v private.provider_credentials;begin
  perform private.require_role(array['policy_role','ingress_role','voice_role']);perform private.assert_mission(p_mission);
  if private.caller_role()='voice_role'and(p_provider not in('twilio','openai')or not exists(select from public.voice_sessions s where s.mission_id=p_mission and((p_provider='twilio'and s.twilio_ref=p_ref)or(p_provider='openai'and s.openai_ref=p_ref))and not exists(select from public.voice_session_events e where e.session_id=s.id and e.kind='ended')))then raise exception 'invariant_violation: voice credential capability denied';end if;
  select c.*into strict v from private.provider_credentials c join public.missions m on m.id=c.mission_id join public.founder_accounts a on a.id=c.account_id and a.founder_id=m.founder_id where c.mission_id=p_mission and c.ref=p_ref and c.provider=p_provider and c.sandbox_mode=p_sandbox and m.sandbox_mode=p_sandbox and a.status='connected'and not exists(select from public.account_revocations r where r.account_id=a.id);
  return jsonb_build_object('encrypted',v.encrypted,'accountId',v.account_id,'ref',v.ref);
end$$;
create or replace function public.provider_connection(p_mission uuid,p_provider text,p_account uuid default null)returns jsonb language plpgsql security definer set search_path=''as $$declare v private.provider_credentials;begin
  perform private.require_role(array['policy_role','ingress_role']);perform private.assert_mission(p_mission);
  select c.*into strict v from private.provider_credentials c join public.founder_accounts a on a.id=c.account_id join public.missions m on m.id=c.mission_id and m.founder_id=a.founder_id where c.mission_id=p_mission and c.provider=p_provider and(p_account is null or c.account_id=p_account)and c.sandbox_mode=m.sandbox_mode and a.status='connected'and not exists(select from public.account_revocations r where r.account_id=a.id)order by c.created_at desc limit 1;
  return jsonb_build_object('ref',v.ref,'accountId',v.account_id,'sandboxMode',v.sandbox_mode);
end$$;
commit;
